+body {
+    margin: 0;
+    font-family: Verdana, Arial, sans-serif; 
+    box-sizing: border-box;
+    background-color: #f1f1f1; 
+    line-height: 1.6;
+}
+
+
+header {
+    background-color: #04AA6D;
+    color: white;
+    padding: 16px 24px;
+    font-size: 24px;
+    font-weight: bold;
+     position: sticky;  /* หรือ fixed ก็ได้ */
+    top: 0;            /* ติดด้านบน */
+    z-index: 1000;     /* อยู่เหนือ content */
+}
+
+.navbar ul {
+    list-style: none;
+    display: flex;
+    gap: 15px;
+    padding: 0;
+    margin: 0;
+}
+
+.navbar ul li a {
+    color: white;
+    text-decoration: none;
+}
+
+/* =========================
+   Sidebar
+   ========================= */
+.layout {  /* แนะนำให้เพิ่ม div ครอบ sidebar + main-content */
+    display: flex;
+    max-width: 1200px;
+    margin: 0 auto;
+}
+
+#sidebar {
+    width: 220px;
+    background-color: #e7e9eb; /* สีอ่อนแบบ W3Schools */
+    padding: 16px;
+    height: 100vh;
+    overflow-y: auto;
+    flex-shrink: 0;
+    position: sticky;  /* sidebar ติดเวลา scroll */
+    top: 0;
+}
+
+#sidebar ul {
+    list-style: none;
+    padding: 0;
+}
+
+#sidebar ul li {
+    margin-bottom: 10px;
+}
+
+#sidebar ul li a {
+    text-decoration: none;
+    color: #333;
+    display: block;
+    padding: 8px;
+    border-radius: 4px;
+    transition: background 0.3s;
+}
+
+#sidebar ul li a:hover {
+    background-color: #ddd;
+}
+
+/* =========================
+   Main Content
+   ========================= */
+#main-content {
+    flex: 1;  /* ขยายเต็มที่ตามพื้นที่ layout */
+    background-color: #fff;
+    padding: 32px;
+    max-width: 960px; /* เหมือน W3Schools */
+    margin-top: 70px; /* ความสูง header */
+}
+
+/* กรณีหน้า index.html ไม่มี sidebar */
+body.index #main-content {
+    margin-left: 0;
+    max-width: 700px;        /* กว้างเท่ากับหน้าที่มี sidebar */
+    margin: 0 auto;          /* จัด content กลางหน้า */
+}
+
+/* =========================
+   Footer
+   ========================= */
+footer {
+    background-color: #333;
+    color: white;
+    text-align: center;
+    padding: 15px;
+}
+
+@media screen and (max-width: 768px) {
+    .layout {
+        flex-direction: column;
+    }
+
+    #sidebar {
+        width: 100%;
+        height: auto;
+        position: relative;
+    }
+
+    #main-content {
+        max-width: 100%;
+        padding: 15px;
+    }
+}
+
+
+/* =========================
+   Empty sidebar
+   ========================= */
+#sidebar.empty-sidebar {
+    background-color: #fff;   /* สีเดียวกับ container */
+           /* คง padding เดิมถ้าอยากให้ layoutเหมือนหน้าที่มี sidebar */
+    /* อย่าแก้ width หรือ float */
+}
+
+/* หน้า login ให้ layout อยู่กลางและสวยขึ้น */
+body.login-page #main-content {
+    max-width: 400px;       /* กว้างแค่พอ form */
+    margin: 50px auto;      /* จัดกลางแนวนอนและเว้นบน */
+    padding: 20px;
+    background-color: #fff; /* เหมือน container */
+    border-radius: 8px;
+    box-shadow: 0 0 10px rgba(0,0,0,0.1);
+}
+
+
+
+/* หน้า register ให้ layout อยู่กลางเหมือน login */
+body.register-page #main-content {
+    max-width: 400px;          /* กว้างพอ form */
+    margin: 50px auto;         /* จัดกลางหน้า */
+    padding: 20px;
+    background-color: #fff;    /* เหมือน container */
+    border-radius: 8px;
+    box-shadow: 0 0 10px rgba(0,0,0,0.1);
+}
+
+
+
