+    list-style: none;
+    padding: 0;
+}
+
+#sidebar ul li {
+    margin-bottom: 10px;
+}
+
+#sidebar ul li a {
+    text-decoration: none;
+    color: #333;
+    display: block;
+    padding: 8px;
+    border-radius: 4px;
+    transition: background 0.3s;
+}
+
+#sidebar ul li a:hover {
+    background-color: #ddd;
+}
+
+/* =========================
+   Main Content
+   ========================= */
+#main-content {
+    flex: 1;  /* ขยายเต็มที่ตามพื้นที่ layout */
+    background-color: #fff;
+    padding: 32px;
+    
+    margin-left: 240px;
+    
+  
+}
+
+/* กรณีหน้า index.html ไม่มี sidebar */
+body.index #main-content {
+    margin-left: 0;
+    max-width: 700px;        /* กว้างเท่ากับหน้าที่มี sidebar */
+    margin: 0 auto;          /* จัด content กลางหน้า */
+}
+
+/* =========================
+   Footer
+   ========================= */
+footer {
+    background-color: #333;
+    color: white;
+    text-align: center;
+    padding: 15px;
+    position: relative;
+    z-index: 100; /* สูงกว่า sidebar */
+}
+
+@media screen and (max-width: 768px) {
+    .layout {
+        flex-direction: column;
+    }
+
+    #sidebar {
+        width: 100%;
+        height: auto;
+        position: relative;
+    }
+
+    #main-content {
+        max-width: 100%;
+        padding: 15px;
+    }
+}
+
+
+/* =========================
