+    box-shadow: 0 0 10px rgba(0,0,0,0.1);
+}
+
+/* =========================
+   Quiz
+   ========================= */
+#quiz-container {
+    max-width: 600px;
+    margin: auto;
+    text-align: center;
+}
+
+#timer {
+    font-size: 18px;
+    margin-bottom: 10px;
+}
+
+.choices {
+    display: grid;
+    grid-template-columns: 1fr 1fr;
+    gap: 15px;
+    margin-top: 20px;
+}
+
+.choice {
+    padding: 20px;
+    font-size: 18px;
+    color: white;
+    border: none;
+    border-radius: 8px;
+    cursor: pointer;
+}
+
+.choice:hover {
+    opacity: 0.9;
+}
